    {
      "candidate_id": "C03",
      "verdict": "true_drift",
      "reason": "The top-level helper `httpx.get()` does not accept an `extensions` keyword, so the documented call would raise an unexpected keyword argument error.",
      "code_citation": {
        "path": "httpx/_api.py",
        "start_line": 174,
        "end_line": 186,
        "quote": "def get(\n    url: URL | str,\n    *,\n    params: QueryParamTypes | None = None,\n    headers: HeaderTypes | None = None,\n    cookies: CookieTypes | None = None,\n    auth: AuthTypes | None = None,\n    proxy: ProxyTypes | None = None,\n    follow_redirects: bool = False,\n    verify: ssl.SSLContext | str | bool = True,\n    timeout: TimeoutTypes = DEFAULT_TIMEOUT_CONFIG,\n    trust_env: bool = True,\n) -> Response:"
      },
      "suggested_doc_fix": "Use an explicit client: `client = httpx.Client(); response = client.get(\"https://www.example.com\", extensions=extensions)`."
    },
    {
      "candidate_id": "C04",
      "verdict": "true_drift",
      "reason": "The top-level helper `httpx.request()` does not accept an `extensions` keyword, so the documented call would raise an unexpected keyword argument error.",
      "code_citation": {
        "path": "httpx/_api.py",
        "start_line": 39,
        "end_line": 56,
        "quote": "def request(\n    method: str,\n    url: URL | str,\n    *,\n    params: QueryParamTypes | None = None,\n    content: RequestContent | None = None,\n    data: RequestData | None = None,\n    files: RequestFiles | None = None,\n    json: typing.Any | None = None,\n    headers: HeaderTypes | None = None,\n    cookies: CookieTypes | None = None,\n    auth: AuthTypes | None = None,\n    proxy: ProxyTypes | None = None,\n    timeout: TimeoutTypes = DEFAULT_TIMEOUT_CONFIG,\n    follow_redirects: bool = False,\n    verify: ssl.SSLContext | str | bool = True,\n    trust_env: bool = True,\n) -> Response:"
      },
      "suggested_doc_fix": "Use an explicit client: `client = httpx.Client(); response = client.request(\"CONNECT\", \"https://www.example.com\", extensions=extensions)`."
    },
    {
      "candidate_id": "C05",
      "verdict": "true_drift",
      "reason": "HTTPX does not export a `Mounts` class; client mounts are plain mappings passed to `mounts=...`.",
      "code_citation": {
        "path": "httpx/_transports/__init__.py",
        "start_line": 7,
        "end_line": 15,
        "quote": "__all__ = [\n    \"ASGITransport\",\n    \"AsyncBaseTransport\",\n    \"BaseTransport\",\n    \"AsyncHTTPTransport\",\n    \"HTTPTransport\",\n    \"MockTransport\",\n    \"WSGITransport\",\n]"
      },
      "suggested_doc_fix": "Replace `httpx.Mounts(...)` with a plain dictionary assigned to `mounts`, then pass it as `client = httpx.Client(mounts=mounts)`."
    },
    {
      "candidate_id": "C06",
      "verdict": "true_drift",
      "reason": "The example constructs `httpx.Mounts(...)`, but the client's `mounts` argument is a mapping of URL patterns to transports or `None`.",
      "code_citation": {
        "path": "httpx/_transports/__init__.py",
        "start_line": 7,
        "end_line": 15,
        "quote": "__all__ = [\n    \"ASGITransport\",\n    \"AsyncBaseTransport\",\n    \"BaseTransport\",\n    \"AsyncHTTPTransport\",\n    \"HTTPTransport\",\n    \"MockTransport\",\n    \"WSGITransport\",\n]"
      },
      "suggested_doc_fix": "Use `mounts = {'http://': HTTPSRedirect(), 'https://': httpx.HTTPTransport()}` and `client = httpx.Client(mounts=mounts)`."
    },
    {
      "candidate_id": "C07",
      "verdict": "false",
      "reason": "In that compatibility example, `session` is an instance of `requests.Session`, not `httpx.Client`; the snippet is illustrating the requests API before showing the HTTPX equivalent.",
      "code_citation": {
        "path": "docs/compatibility.md",
        "start_line": 53,
        "end_line": 56,
        "quote": "session = requests.Session()\nrequest = requests.Request(\"GET\", ...).prepare()\nwhile request is not None:\n    response = session.send(request, allow_redirects=False)"
      },
      "suggested_doc_fix": ""
    },
    {
      "candidate_id": "C08",
      "verdict": "false",
      "reason": "The documentation is comparing exception hierarchies: `RequestException` is a requests API name, while HTTPX exposes `HTTPError`; it is not claiming that HTTPX defines `RequestException`.",
      "code_citation": {
        "path": "httpx/_exceptions.py",
        "start_line": 2,
        "end_line": 5,
        "quote": "Our exception hierarchy:\n\n* HTTPError"
      },
      "suggested_doc_fix": ""
    },
    {
      "candidate_id": "C09",
      "verdict": "true_drift",
      "reason": "The WSGI transport docstring still recommends `httpx.Client(app=app)`, but `Client` has no `app` parameter; the app must be passed to `WSGITransport(app=app)`.",
      "code_citation": {
        "path": "httpx/_client.py",
        "start_line": 639,
        "end_line": 661,
        "quote": "    def __init__(\n        self,\n        *,\n        auth: AuthTypes | None = None,\n        params: QueryParamTypes | None = None,\n        headers: HeaderTypes | None = None,\n        cookies: CookieTypes | None = None,\n        verify: ssl.SSLContext | str | bool = True,\n        cert: CertTypes | None = None,\n        trust_env: bool = True,\n        http1: bool = True,\n        http2: bool = False,\n        proxy: ProxyTypes | None = None,\n        mounts: None | (typing.Mapping[str, BaseTransport | None]) = None,\n        timeout: TimeoutTypes = DEFAULT_TIMEOUT_CONFIG,\n        follow_redirects: bool = False,\n        limits: Limits = DEFAULT_LIMITS,\n        max_redirects: int = DEFAULT_MAX_REDIRECTS,\n        event_hooks: None | (typing.Mapping[str, list[EventHook]]) = None,\n        base_url: URL | str = \"\",\n        transport: BaseTransport | None = None,\n        default_encoding: str | typing.Callable[[bytes], str] = \"utf-8\",\n    ) -> None:"
      },
      "suggested_doc_fix": "Replace `client = httpx.Client(app=app)` with `transport = httpx.WSGITransport(app=app); client = httpx.Client(transport=transport)`."
    },
    {
      "candidate_id": "C10",
      "verdict": "true_drift",
      "reason": "`httpx.Client(...)` has no `app` parameter, although the WSGI docstring calls it with `app=app`.",
      "code_citation": {
        "path": "httpx/_client.py",
        "start_line": 639,
        "end_line": 661,
        "quote": "    def __init__(\n        self,\n        *,\n        auth: AuthTypes | None = None,\n        params: QueryParamTypes | None = None,\n        headers: HeaderTypes | None = None,\n        cookies: CookieTypes | None = None,\n        verify: ssl.SSLContext | str | bool = True,\n        cert: CertTypes | None = None,\n        trust_env: bool = True,\n        http1: bool = True,\n        http2: bool = False,\n        proxy: ProxyTypes | None = None,\n        mounts: None | (typing.Mapping[str, BaseTransport | None]) = None,\n        timeout: TimeoutTypes = DEFAULT_TIMEOUT_CONFIG,\n        follow_redirects: bool = False,\n        limits: Limits = DEFAULT_LIMITS,\n        max_redirects: int = DEFAULT_MAX_REDIRECTS,\n        event_hooks: None | (typing.Mapping[str, list[EventHook]]) = None,\n        base_url: URL | str = \"\",\n        transport: BaseTransport | None = None,\n        default_encoding: str | typing.Callable[[bytes], str] = \"utf-8\",\n    ) -> None:"
      },
      "suggested_doc_fix": "Replace the docstring example's `client = httpx.Client(app=app)` with the explicit WSGI transport form."
    }
  ],
  "additional_findings": [
    {
      "finding_id": "AD-1",
      "drift_kind": "signature",
      "explanation": "This documentation example uses the pre-0.18.0 low-level transport signature that accepts positional method/url/headers/stream values and returns a tuple, but the current transport API uses `handle_request(request)` and returns a `Response`.",
      "doc_citation": {
        "path": "docs/advanced/transports.md",
        "start_line": 286,
        "end_line": 295,
        "quote": "    def handle_request(self, method, url, headers, stream, extensions):\n        scheme, host, port, path = url\n        if port is None:\n            location = b\"https://%s%s\" % (host, path)\n        else:\n            location = b\"https://%s:%d%s\" % (host, port, path)\n        stream = httpx.ByteStream(b\"\")\n        headers = [(b\"location\", location)]\n        extensions = {}\n        return 303, headers, stream, extensions"
      },
      "code_citation": {
        "path": "httpx/_transports/base.py",
        "start_line": 26,
        "end_line": 27,
        "quote": "    def handle_request(self, request: Request) -> Response:"
      },
      "proposed_fix": "Update the example to implement `handle_request(self, request)` and return `httpx.Response(...)`, using `request.url` for the redirect target."
    },
    {
      "finding_id": "AD-2",
      "drift_kind": "other",
      "explanation": "The progress-monitoring note refers to `response.iter_content()`, which is a requests API name and does not exist on httpx's `Response`; HTTPX provides `response.iter_bytes()`.",
      "doc_citation": {
        "path": "docs/advanced/clients.md",
        "start_line": 183,
        "end_line": 183,
        "quote": "This interface is required for properly determining download progress, because the total number of bytes returned by `response.content` or `response.iter_content()` will not always correspond with the raw content length of the response if HTTP response compression is being used."
      },
      "code_citation": {
        "path": "httpx/_models.py",
        "start_line": 884,
        "end_line": 884,
        "quote": "    def iter_bytes(self, chunk_size: int | None = None) -> typing.Iterator[bytes]:"
      },
      "proposed_fix": "Change `response.iter_content()` to `response.iter_bytes()` in the explanatory text."
    },
    {
      "finding_id": "AD-3",
      "drift_kind": "other",
      "explanation": "The documented complex-proxy example is not valid `mounts` configuration syntax; mounts should be a mapping from URL patterns to transports or `None`.",
      "doc_citation": {
        "path": "docs/compatibility.md",
        "start_line": 168,
        "end_line": 168,
        "quote": "This change is for better consistency with more complex mappings, that might also include domain names, such as `mounts={\"all://\": ..., httpx.HTTPTransport(proxy=\"all://www.example.com\": None})` which maps all requests onto a proxy, except for requests to \"www.example.com\" which have an explicit exclusion."
      },
      "code_citation": {
        "path": "httpx/_client.py",
        "start_line": 652,
        "end_line": 652,
        "quote": "        mounts: None | (typing.Mapping[str, BaseTransport | None]) = None,"
      },
      "proposed_fix": "Rewrite the example as a mapping, e.g. `mounts={\"all://\": httpx.HTTPTransport(proxy=\"http://proxy\"), \"all://www.example.com\": None}`."
    }
  ]
}
